CREATE PROCEDURE [cache_dati_grafico_giornaliero_selectrow]
	@P_1 VarChar(15),
	@P_3 Date,
	@sync_scope_local_id Int,
	@sync_scope_restore_count Int
AS
BEGIN
SELECT [side].[CodMac], [side].[DataRil], [base].[tipo], [base].[EUIncassiMonete], [base].[EUIncassiGettoni], [base].[EUPremiPagati], [base].[EUTicketsPagati], [base].[NrMonete], [base].[NrGettoni], [base].[NrPremi], [base].[NrTickets], [base].[NrGettoniOut], [base].[NrMoneteOut], [base].[NPartite], [side].[sync_row_is_tombstone], [side].[local_update_peer_timestamp] as sync_row_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then COALESCE([side].[restore_timestamp], [side].[local_update_peer_timestamp]) else [side].[scope_update_peer_timestamp] end as sync_update_peer_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_update_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_update_peer_key] end else [side].[scope_update_peer_key] end as sync_update_peer_key, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then [side].[local_create_peer_timestamp] else [side].[scope_create_peer_timestamp] end as sync_create_peer_timestamp, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_create_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_create_peer_key] end else [side].[scope_create_peer_key] end as sync_create_peer_key from [cache_dati_grafico_giornaliero] [base] right join [cache_dati_grafico_giornaliero_tracking] [side] on [base].[CodMac] = [side].[CodMac] and [base].[DataRil] = [side].[DataRil] WHERE [side].[CodMac] = @P_1 AND [side].[DataRil] = @P_3
END
